\begin{align*} \frac{1}{2} \| \mathbf{u} \times \mathbf{v} \| &= \frac{1}{2} \| (\mathbf{p} + 2 \mathbf{q}) \times (2 \mathbf{p} + \mathbf{q}) \| \\ &= \frac{1}{2} \| \mathbf{p} \times (2 \mathbf{p}) + \mathbf{p} \times \mathbf{q} + 4 \mathbf{q} \times \mathbf{p} + 2 \mathbf{q} \times \mathbf{q} \| \\ &= \frac{1}{2} \| \mathbf{0} + \mathbf{p} \times \mathbf{q} - 4 \mathbf{p} \times \mathbf{q} + \mathbf{0} \| \\ &= \frac{1}{2} \| -3 \mathbf{p} \times \mathbf{q} \| \\ &= \frac{3}{2} \| \mathbf{p} \times \mathbf{q} \| \\ &= \frac{3}{2} \| \mathbf{p} \| \| \mathbf{q} \| \sin 30^\circ \\ &= \frac{3}{2} (1)(1) \left( \frac{1}{2} \right) \\ &= \frac{3}{4}. \end{align*}

