\begin{align*} \sin 17^\circ + \sin 43^\circ &= 2 \sin \frac{17^\circ + 43^\circ}{2} \cos \frac{17^\circ - 43^\circ}{2} \\ &= 2 \sin \frac{60^\circ}{2} \cos \frac{-26^\circ}{2} \\ &= 2 \sin 30^\circ \cos (-13^\circ) \\ &= 2 \cdot \frac{1}{2} \cos 13^\circ \\ &= \cos 13^\circ. \end{align*}

